import { Button } from 'app/components/ui-kits/atoms/zimmButton/zimmButton.css';
import { ZimmFooter } from 'app/components/footer/footer.css';
import { ZimmFooterNavColumn } from 'app/components/footer/footerNavColumn/footerNavColumn.css';
import { ZimmFooterBottomBar } from 'app/components/footer/bottomBar/bottomBar.css';
import { ZimmModal } from 'app/components/ui-kits/atoms/zimmModal/zimmModal.css';
import { ZimmSubscribeModal } from 'app/components/ui-kits/organisms/zimmSubscribeModal/zimmSubscribeModal.css';
import { ZimmSubscribeSection } from 'app/components/ui-kits/organisms/zimmSubscribeSection/zimmSubscribeSection.css';
import { ZimmContactIconRow } from 'app/components/ui-kits/molecules/zimmContactIconRow/zimmContactIconRow.css';
import { Header } from './header';
import { ListMenu } from './listMenu';
import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem/zimmNavItem.css';
import { ZimmTextInput } from 'app/components/ui-kits/atoms/zimmTextInput/zimmTextInput.css';
import { ZimmProductContent } from 'app/components/ui-kits/molecules/zimmProductContent/zimmProductContent.css';
import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription/zimmProductDescription.css';
import { ZimmProductPrice } from 'app/components/ui-kits/atoms/zimmProductPrice/zimmProductPrice.css';
import { ZimmProductStyleCode } from 'app/components/ui-kits/atoms/zimmProductStyleCode/zimmProductStyleCode.css';

export const components = {
  Button,
  ZimmFooter,
  ZimmFooterNavColumn,
  ZimmFooterBottomBar,
  ZimmModal,
  ZimmSubscribeModal,
  ZimmSubscribeSection,
  ZimmContactIconRow,
  Header,
  ListMenu,
  ZimmNavItem,
  ZimmTextInput,
  ZimmProductContent,
  ZimmProductDescription,
  ZimmProductPrice,
  ZimmProductStyleCode,
};

import { defineStyleConfig } from '@chakra-ui/react';

const BUTTON_PRESSED = 'var(--zimm-color-action-primary-bg-pressed)';
// No --zimm-focus-ring-inverse CSS var yet — inline until designer adds one to zimmTokens.
const FOCUS_RING_INVERSE = 'var(--zimm-border-width-default) solid var(--zimm-color-action-primary-text)';

// Icon-variant opacity levels. No foundation opacity token covers element-level opacity
// (colors.opacity holds RGBA overlays, not multipliers), so named constants are the
// correct pattern per conventions.md > "No magic numbers or strings."
const OPACITY_ICON_HOVER = 0.6;
const OPACITY_ICON_DISABLED = 0.4;
// 0.15s, matching baseStyle. Deliberately NOT var(--zimm-motion-duration-fast) (200ms):
// see baseStyle's transition comment above — that decision was to leave 0.15s as-is pending
// the UI designer rather than retime silently, and motion.ts is itself marked provisional.
// Retiming only the icon variants would leave this file running two different durations.
// One constant so icon/iconInverse cannot drift.
const ICON_TRANSITION = 'opacity 0.15s ease';

// fontFamily/fontWeight/lineHeight/letterSpacing/textTransform come from sizes.lg/sm's
// textStyle (below), not here — button always renders with a size (defaultProps.size
// is 'lg', there's no sizeless render path), so a duplicate fallback here would only
// ever mask the per-size textStyle value instead of letting it apply.
const baseStyle = {
  borderRadius: 0,
  // 0.15s matches no motion token (fast 200ms / default 300ms) — left as-is
  // pending the UI designer's confirmation rather than retimed silently.
  transition: 'background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease',
  // Focus ring per Handover button.md §focus: outline only, no background change.
  // Replaces the previous outline:none + bg-swap, which gave the primary variant an
  // invisible focus state (#191919 default vs #000000 focus) — a WCAG 2.4.7 failure.
  // Light-mode ring (border-focus). Dark-surface / inverse ring (grey-white) is the
  // separate deferred inverse-focus item, owned with the UI designer.
  _focusVisible: {
    outline: 'var(--zimm-focus-ring)',
    outlineOffset: 'var(--zimm-focus-ring-offset-default)',
    boxShadow: 'none',
  },
};

const variants = {
  primary: {
    bg: 'var(--zimm-color-text-default)',
    color: 'var(--zimm-color-text-inverse)',
    border: 'var(--zimm-border-width-default) solid',
    borderColor: 'var(--zimm-color-text-default)',
    _hover: {
      bg: 'var(--zimm-color-text-inverse-grey)',
      borderColor: 'var(--zimm-color-text-inverse-grey)',
      _disabled: { bg: 'var(--zimm-color-border-secondary)', borderColor: 'var(--zimm-color-border-secondary)' },
    },
    _active: {
      bg: BUTTON_PRESSED,
      borderColor: BUTTON_PRESSED,
    },
    _disabled: {
      bg: 'var(--zimm-color-border-secondary)',
      borderColor: 'var(--zimm-color-border-secondary)',
      color: 'var(--zimm-color-text-inverse)',
      opacity: 1,
      cursor: 'not-allowed',
    },
    // Focus ring inherited from baseStyle (2px offset), per Handover button.md.
  },
  primaryInverse: {
    bg: 'var(--zimm-color-action-primary-text)',
    color: 'var(--zimm-color-action-primary-bg-default)',
    border: 'none',
    _hover: {
      bg: 'var(--zimm-color-action-secondary-bg-hover)',
      _disabled: { bg: 'var(--zimm-color-action-primary-bg-disabled)' },
    },
    _active: {
      bg: BUTTON_PRESSED,
      color: 'var(--zimm-color-action-primary-text)',
    },
    _disabled: {
      bg: 'var(--zimm-color-action-primary-bg-disabled)',
      color: 'var(--zimm-color-action-primary-text-disabled)',
      opacity: 1,
      cursor: 'not-allowed',
    },
    _focusVisible: {
      outline: FOCUS_RING_INVERSE,
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
  secondary: {
    bg: 'var(--zimm-color-bg-07)',
    color: 'var(--zimm-color-text-default)',
    border: 'var(--zimm-border-width-default) solid',
    borderColor: 'var(--zimm-color-text-default)',
    _hover: {
      bg: 'var(--zimm-color-bg-01)',
      borderColor: 'var(--zimm-color-text-default)',
      _disabled: { bg: 'transparent', borderColor: 'var(--zimm-color-text-inverse-grey)' },
    },
    _active: {
      bg: BUTTON_PRESSED,
      borderColor: BUTTON_PRESSED,
      color: 'var(--zimm-color-text-inverse)',
    },
    _disabled: {
      bg: 'transparent',
      borderColor: 'var(--zimm-color-text-inverse-grey)',
      color: 'var(--zimm-color-text-muted)',
      opacity: 1,
      cursor: 'not-allowed',
    },
    // Handover button.md §focus: outline only (no background change); 3px offset on
    // secondary to clear its 1px border. Stated explicitly rather than relying on
    // baseStyle merge, so the ring can't be lost to variant-override semantics.
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-secondary)',
      boxShadow: 'none',
    },
  },
  secondaryInverse: {
    bg: 'transparent',
    color: 'var(--zimm-color-action-primary-text)',
    border: 'var(--zimm-border-width-default) solid',
    borderColor: 'var(--zimm-color-action-primary-text)',
    _hover: {
      bg: 'var(--zimm-color-action-secondary-bg-hover)',
      _disabled: {
        bg: 'transparent',
        borderColor: 'var(--zimm-color-action-secondary-text-disabled)',
      },
    },
    _active: {
      bg: BUTTON_PRESSED,
      borderColor: BUTTON_PRESSED,
      color: 'var(--zimm-color-action-primary-text)',
    },
    _disabled: {
      bg: 'transparent',
      borderColor: 'var(--zimm-color-action-secondary-text-disabled)',
      color: 'var(--zimm-color-action-secondary-text-disabled)',
      opacity: 1,
      cursor: 'not-allowed',
    },
    _focusVisible: {
      outline: FOCUS_RING_INVERSE,
      outlineOffset: 'var(--zimm-focus-ring-offset-secondary)',
      boxShadow: 'none',
    },
  },
  // Icon-only variant — opacity-based hover; transition overrides baseStyle to include opacity.
  icon: {
    bg: 'transparent',
    border: 'none',
    color: 'var(--zimm-color-action-primary-bg-default)',
    transition: ICON_TRANSITION,
    _hover: {
      bg: 'transparent',
      opacity: OPACITY_ICON_HOVER,
    },
    _active: {
      bg: 'transparent',
      opacity: 1,
    },
    _disabled: {
      bg: 'transparent',
      opacity: OPACITY_ICON_DISABLED,
      cursor: 'not-allowed',
    },
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
  iconInverse: {
    bg: 'transparent',
    border: 'none',
    color: 'var(--zimm-color-action-primary-text)',
    transition: ICON_TRANSITION,
    _hover: {
      bg: 'transparent',
      opacity: OPACITY_ICON_HOVER,
    },
    _active: {
      bg: 'transparent',
      opacity: 1,
    },
    _disabled: {
      bg: 'transparent',
      opacity: OPACITY_ICON_DISABLED,
      cursor: 'not-allowed',
    },
    _focusVisible: {
      outline: FOCUS_RING_INVERSE,
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
};

// PROVISIONAL prototype button dimensions. The Handover's action tokens specify 52px (lg) /
// 40px (md) — see actionSizes in foundation/sizes.ts. Reconciling prototype ↔ Handover is a
// UI-designer decision (Hard Rule #3), pending sign-off, so the prototype values are named
// here to make the temporary exception explicit rather than switched silently. The 5px
// vertical padding has no token counterpart.
const BTN_HEIGHT_LG = '50px';
const BTN_HEIGHT_SM = '41px';
const BTN_PADDING_Y = '5px';

// `textStyle` is a special key Chakra's style engine expands wherever it appears (see
// link.ts) — resolves against the full registered textStyles.button/buttonSm
// (foundation/typography.ts), the single source for fontFamily/fontSize/fontWeight/
// lineHeight/letterSpacing/textTransform.
const sizes = {
  lg: {
    h: BTN_HEIGHT_LG,
    px: 'var(--zimm-scale-xl)',
    py: BTN_PADDING_Y,
    textStyle: 'button',
  },
  sm: {
    h: BTN_HEIGHT_SM,
    px: 'var(--zimm-scale-xl)',
    py: BTN_PADDING_Y,
    textStyle: 'buttonSm',
  },
  // WCAG 2.2 AA SC 2.5.8 — 24px minimum target size. SFCC-55's accessibility note names this
  // control specifically ("the minimum size of that email sign up button").
  //
  // minW/minH, NOT padding: Chakra's IconButton hard-sets `padding: "0"` as a *style prop*, and
  // style props merge after __css, so any p/px/py declared here is silently discarded. The
  // previous `p: 'xs'` read as a 32px target and rendered 16x16 — the icon's own boxSize.
  //
  // var, not 'xl': min-width/height resolve through theme.sizes (xl = 36rem = 576px), not
  // theme.space. Same rule and same token as clearButton in zimmTextInput.ts, which is the
  // sibling control in the same trailing slot.
  icon: {
    h: 'auto',
    minW: 'var(--zimm-scale-xl)',
    minH: 'var(--zimm-scale-xl)',
  },
};

export const Button = defineStyleConfig({
  baseStyle,
  variants,
  sizes,
  defaultProps: {
    variant: 'primary',
    size: 'lg',
  },
});

import type { SystemStyleObject } from '@chakra-ui/react';

// Figma Textfield flush variant (node 40000265:374): field/border/* tokens.
// hover and filled (has value, unfocused) both darken to focus colour per Figma spec.
const BORDER = {
  default: 'var(--zimm-color-border-forms)', // #707070 — Figma field/border/default
  hover: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/hover
  filled: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/filled
  focus: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/focus
  error: 'var(--zimm-color-status-error)', // #9c0000 — Figma field/border/error
} as const;

// Figma field/border/inverse/default = white (opaque), inverse/error = #f98f8c (coral).
// Figma does not spec inverse/hover or inverse/focus separately — same white as default.
const BORDER_INVERSE = {
  default: 'var(--zimm-color-text-inverse)',
  hover: 'var(--zimm-color-text-inverse)',
  filled: 'var(--zimm-color-text-inverse)',
  focus: 'var(--zimm-color-text-inverse)',
  error: 'var(--zimm-color-status-error-bg)', // #f98f8c
} as const;

// Figma: Textfield flush floated label — brand/font/size/250 (10px) / medium weight.
const LABEL_FLOATED_SIZE = 'var(--zimm-font-size-4xs)';
const LABEL_FLOATED_WEIGHT = 'var(--zimm-font-weight-medium)';
// Figma: content div h-[36px] — pending alias/size/field/height token from the designer.
// rem, not px: this height participates in a rem-derived measurement, so it has to scale with the
// root font-size (WCAG 1.4.4 — see overrideStyling.md > Units). footer.css.ts's SIZE_SUBSCRIBE_SLOT
// analogue in zimmSubscribeSection.css.ts (2.8125rem) documents itself as "36px content + 4px/4px
// padding + 1px border"; freezing the content height in px broke that derivation as soon as the
// root font-size moved — at 200% zoom the slot reached 90px while the field reached only 53px,
// over-reserving by ~37px. (Dead space, not clipping — the no-layout-shift guarantee held either
// way.) In rem it holds at every zoom level. This file is now developer-owned per the co-location
// pattern (overrideStyling.md), but the value itself is still PROVISIONAL pending Kiera — this
// should ride along with that sign-off, not land silently.
const FIELD_CONTENT_HEIGHT = '2.25rem'; // 36px at the default 16px root
// No opacity token in foundation yet — pending Tier 1 PR with UI-designer sign-off.
const OPACITY_DISABLED = 0.4;

const MOTION = 'var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)';

/** State the component feeds in so the recipe can resolve the Figma colour cascade. */
export type ZimmTextInputStyleProps = {
  inverse?: boolean;
  disabled?: boolean;
  hasError?: boolean;
  focused?: boolean;
  /** Field has a value. Combined with `focused` this gives the floated-label state. */
  filled?: boolean;
};

const palette = (inverse?: boolean) => (inverse ? BORDER_INVERSE : BORDER);

/** Border colour precedence: disabled > error > focus > filled > default. */
export const resolveBorderColour = ({ inverse, disabled, hasError, focused, filled }: ZimmTextInputStyleProps) => {
  const p = palette(inverse);
  if (disabled) return p.default;
  if (hasError) return p.error;
  if (focused) return p.focus;
  if (filled) return p.filled;
  return p.default;
};

/** In error the hover colour holds (error > hover); otherwise it darkens to focus. */
export const resolveHoverBorderColour = (props: ZimmTextInputStyleProps) =>
  props.hasError ? resolveBorderColour(props) : palette(props.inverse).hover;

// Figma text/subtle = #666 for the floated/disabled label in light mode;
// text/inverse/subtle = #969696 in inverse mode.
export const resolveLabelColour = ({ inverse, disabled, focused, filled }: ZimmTextInputStyleProps) => {
  const floated = Boolean(focused || filled);
  if (disabled) return inverse ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-secondary)';
  if (inverse) return floated ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-inverse)';
  return floated ? 'var(--zimm-color-text-secondary)' : 'var(--zimm-color-text-default)';
};

export const ZimmTextInput = {
  parts: ['root', 'row', 'content', 'label', 'input', 'clearButton', 'helper', 'error'],
  baseStyle: (props: ZimmTextInputStyleProps): Record<string, SystemStyleObject> => {
    const { inverse, disabled, focused, filled } = props;
    const floated = Boolean(focused || filled);
    const textColour = inverse ? 'var(--zimm-color-text-inverse)' : 'var(--zimm-color-text-default)';

    return {
      root: {
        display: 'block',
        width: '100%',
        opacity: disabled ? OPACITY_DISABLED : 1,
      },

      // Flush bottom-border row. Hover is a CSS pseudo-class, not JS state.
      row: {
        display: 'flex',
        alignItems: 'center',
        gap: 'var(--zimm-scale-xs)',
        borderBottom: `var(--zimm-border-width-default) solid ${resolveBorderColour(props)}`,
        paddingTop: 'var(--zimm-scale-2xs)',
        paddingBottom: 'var(--zimm-scale-2xs)',
        // not in Figma — UX animation on border-colour state changes
        transition: `border-color ${MOTION}`,
        _hover: disabled ? undefined : { borderBottomColor: resolveHoverBorderColour(props) },
      },

      // Figma: content flex-[1_0_0] h-[36px]
      content: { flex: 1, position: 'relative', minHeight: FIELD_CONTENT_HEIGHT },

      label: {
        position: 'absolute',
        left: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontWeight: floated ? LABEL_FLOATED_WEIGHT : 'var(--zimm-font-weight-regular)',
        fontSize: floated ? LABEL_FLOATED_SIZE : 'var(--zimm-font-size-2xs)',
        lineHeight: floated ? undefined : 'var(--zimm-font-lineheight-2xs)',
        color: resolveLabelColour(props),
        top: floated ? 'var(--zimm-scale-3xs)' : '50%',
        transform: floated ? 'none' : 'translateY(-50%)',
        transition: `top ${MOTION}, transform ${MOTION}, font-size ${MOTION}, color ${MOTION}`,
        whiteSpace: 'nowrap',
      },

      input: {
        position: 'absolute',
        bottom: 0,
        left: 0,
        right: 0,
        width: '100%',
        height: 'var(--zimm-scale-l)', // 20px — var, not 'l': theme.sizes has no 'l' key
        background: 'transparent',
        border: 'none',
        outline: 'none',
        fontFamily: 'var(--zimm-font-family-body)',
        fontWeight: 'var(--zimm-font-weight-regular)',
        fontSize: 'var(--zimm-font-size-2xs)',
        color: textColour,
        padding: 0,
        opacity: floated ? 1 : 0,
        cursor: disabled ? 'not-allowed' : 'text',
        transition: `opacity ${MOTION}`,
      },

      clearButton: {
        background: 'transparent',
        border: 'none',
        padding: 0,
        cursor: 'pointer',
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        flexShrink: 0,
        color: textColour,
        // WCAG 2.2 AA SC 2.5.8 — 24px minimum target size
        // var, not 'xl': min-width/height resolve via theme.sizes (xl = 36rem), not theme.space
        minWidth: 'var(--zimm-scale-xl)',
        minHeight: 'var(--zimm-scale-xl)',
        // WCAG 2.2 AA SC 2.4.7 — visible focus state
        _focusVisible: {
          outline: inverse
            ? 'var(--zimm-border-width-default) solid var(--zimm-color-text-inverse)'
            : 'var(--zimm-focus-ring)',
          outlineOffset: 'var(--zimm-focus-ring-offset-default)',
          boxShadow: 'none',
        },
      },

      helper: {
        marginTop: 'var(--zimm-scale-2xs)',
        marginBottom: 0,
        marginInline: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontSize: 'var(--zimm-font-size-3xs)',
        color: inverse ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-secondary)',
      },

      error: {
        marginTop: 'var(--zimm-scale-2xs)',
        marginBottom: 0,
        marginInline: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontSize: 'var(--zimm-font-size-2xs)',
        fontStyle: 'normal',
        fontWeight: 'var(--zimm-font-weight-regular)',
        lineHeight: 'var(--zimm-font-lineheight-2xs)',
        color: inverse ? 'var(--zimm-color-status-error-bg)' : 'var(--zimm-color-status-error)',
      },
    };
  },
};

// alias/size/footer/subscribe-body-max (200px). Provisional, pending a foundation/sizes.ts entry.
// Was a named constant in theme/components/footer.ts before the footer decomposition inlined it;
// restored so the value is named at the point of declaration rather than only commented at use.
const SIZE_SUB_BODY_MAX = '12.5rem';

// 45px — the height ZimmInputAction currently renders (36px content + 4px/4px padding + 1px
// border), so the post-submit slot reserves the same space the control occupied. PROVISIONAL:
// Figma's success state keeps a Textfield instance at 320x59 (node 4019:46044 > Stay In Touch
// Section), so the designed slot is 59px in both states — there is no token for it and
// actionSizes.height offers only 52/40. Pending Kiera. rem, not px: the slot holds text and must
// grow with root font-size (WCAG 1.4.4).
const SIZE_SUBSCRIBE_SLOT = '2.8125rem';

export const ZimmSubscribeSection = {
  parts: ['heading', 'body', 'control', 'success', 'error'],
  baseStyle: {
    // Subscribe heading — Figma node 40000461:10415 binds brand/font/lineHeight/450 (18px).
    // Unlike nav column headings (unbound 100%), this heading has a bound token.
    heading: {
      textStyle: 'navigation',
      // Figma: brand/font/family/body (node 40000538:24875) — deliberate override of
      // textStyles.navigation's heading family.
      fontFamily: 'var(--zimm-font-family-body)',
      margin: 0,
      color: 'var(--zimm-color-text-inverse-grey)',
      lineHeight: 'var(--zimm-font-lineheight-2xs)',
      marginBottom: 'var(--zimm-scale-xl)',
    },
    // Subscribe body paragraph — caption: 12px / 500 / 18px / no uppercase.
    body: {
      textStyle: 'caption',
      fontFamily: 'var(--zimm-font-family-body)', // Figma node 40000538:24875
      margin: 0,
      color: 'var(--zimm-color-text-inverse)',
      maxWidth: SIZE_SUB_BODY_MAX,
      marginBottom: 'var(--zimm-scale-3xl)',
    },
    // Subscribe post-submit confirmation slot — reserves the control slot. minHeight rather than
    // height so copy that genuinely needs a third line on a narrow viewport still grows instead
    // of clipping; centring only positions the content, it does not define the height. See
    // SIZE_SUBSCRIBE_SLOT above for the value's provenance and the outstanding Figma conflict.
    control: {
      minHeight: SIZE_SUBSCRIBE_SLOT,
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
    },
    // Post-submit confirmation — body2: 14px / 400 / 18px.
    // Figma footer/textfield "Subscribed=True": container has py-16px (alias/space/400).
    success: {
      textStyle: 'body2',
      margin: 0,
      color: 'var(--zimm-color-text-inverse)',
    },
    // Failure copy (unavailable/error) — same type scale as success, but the coral
    // "inverse" error colour (text.status.error-bg), not the neutral inverse text colour, so
    // a shopper isn't shown failure copy that visually reads as a success confirmation.
    // Matches the inverse-mode error colour zimmTextInput.css.ts's `error` part already uses.
    error: {
      textStyle: 'body2',
      margin: 0,
      color: 'var(--zimm-color-status-error-bg)',
    },
  },
};

import { breakpoints } from '../foundation/gridSystem';

// Shared between footer's split recipe files (footer.css.ts, footerNavColumn.css.ts,
// bottomBar.css.ts) so a breakpoint or provisional size can't drift between them the way a
// copy-pasted literal would. Not a general-purpose theme module — scope stays footer-only; see
// .claude/rules/overrideStyling.md's co-location guidance for why these no longer live in one
// flat theme/components/footer.ts.

// `tablet` mirrors the confirmed foundation token `breakpoints.md` — imported rather than
// retyped so the two cannot drift apart. `tabletWide` and `desktop` have no foundation
// equivalent yet; `desktop` additionally conflicts with Chakra's lg (62em) and xl (80em), which
// is why every desktop rule using this constant is a raw @media rather than a responsive prop.
// Media queries cannot consume var(), so this is the one deliberate exception to
// theme/components/ otherwise avoiding direct foundation/ imports in favour of --zimm-* CSS vars.
// audit-allow: raw em is correct and permanent here, not a placeholder awaiting a token —
// overrideStyling.md's Units section documents breakpoints as one of the few genuinely
// context-relative uses of em, deliberately outside the var(--zimm-*) scale system.
export const BP = {
  tablet: breakpoints.md, // Figma: alias/breakpoint/tablet — 768px
  tabletWide: '53.75em', // Figma: alias/breakpoint/tablet-wide — 860px (no foundation equivalent)
  desktop: '64em', // Figma: alias/breakpoint/desktop — 1024px (≠ Chakra lg=62em / xl=80em)
} as const;

// alias/size/footer/col-width-nav (140px). Provisional — kept as a named rem reference until
// the UI designer confirms it in foundation/sizes.ts. Used by both the nav column's own width
// (footerNavColumn.css.ts) and the bottom bar's mobile legal-link width (bottomBar.css.ts) — the
// two must match or the legal links stop lining up with the columns above them.
export const SIZE_COL_NAV = '8.75rem';

export const ZimmContactIconRow = {
  parts: ['row', 'iconLink'],
  baseStyle: {
    // Figma: Icon-list has pt-4px (alias/space/100) above it and 4px internal gap between icons.
    row: {
      display: 'flex',
      gap: 'var(--zimm-scale-2xs)',
      alignItems: 'center',
      paddingTop: 'var(--zimm-scale-2xs)',
    },
    // Contact icon touch target — 24px, matches Figma 24x24 (WCAG 2.2 SC 2.5.8).
    // MUST be the CSS var, not the bare token key 'xl': Chakra resolves width/height through
    // theme.sizes, not theme.space, and Chakra's default sizes.xl is 36rem (576px) — which blew
    // each icon up to 576px and destroyed the whole footer layout. foundation/sizes.ts
    // documents why the Zimmermann scale is deliberately not registered as theme.sizes. Same
    // rule applies to boxSize/min/maxWidth/Height.
    iconLink: {
      display: 'inline-flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-xl)',
      height: 'var(--zimm-scale-xl)',
      // ZimmIcon defaults to currentColor — the glyph inherits this.
      color: 'var(--zimm-color-text-inverse)',
      // Focus ring: these render as anchors once a href is supplied, so they are
      // keyboard-reachable and need a visible indicator (WCAG 2.4.7).
      _focusVisible: {
        outline: 'var(--zimm-border-width-default) solid',
        outlineColor: 'var(--zimm-color-text-inverse)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
  },
};

// Generic dialog chrome — overlay + panel + actions row. Component-specific content styling
// (title, fields, consent copy, etc.) belongs in the consuming organism's own recipe, not here —
// see e.g. zimmSubscribeModal.css.ts. Split out of the footer's original combined recipe so a
// future non-subscribe modal has somewhere to register its own chrome and content separately.
export const ZimmModal = {
  parts: ['overlay', 'panel', 'actions'],
  baseStyle: {
    // Rendered through a portal, so it escapes any caller's stacking context.
    overlay: {
      position: 'fixed',
      inset: 0,
      // brand dark overlay (grey-900 base), not pure black
      background: 'var(--zimm-color-opacity-50)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: 'var(--zimm-scale-l)',
      // Chakra zIndices.overlay (1300). Must clear the sticky header, which sets
      // zIndex: 'sticky' (1100) in header.ts. The portal target is document.body, so this
      // competes in the root stacking context, not the caller's.
      zIndex: 'overlay',
    },
    // Light surface — every current use case contrasts against a dark parent (the footer).
    // maxWidth is deliberately NOT set here — ZimmModal takes it as a required prop, since each
    // dialog type has its own Figma-specified size.
    panel: {
      backgroundColor: 'var(--zimm-color-bg-07)',
      width: '100%',
      padding: 'var(--zimm-scale-3xl)',
    },
    actions: { display: 'flex', gap: 'var(--zimm-scale-m)', justifyContent: 'flex-end' },
  },
};

