import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ZimmSubscribeSection } from './index';
import { useSubscribeSection } from 'app/hooks/useSubscribeSection';
import { useUiCopy } from 'app/hooks/useUiCopy';

// See footerNavColumn/index.test.tsx's identical mock for why: ZimmIcon pulls in the base SFCC
// icons barrel, which throws under Vitest (SVG imports resolve to raw path strings here). No
// assertion below depends on an icon's own content.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: (props: { 'aria-label'?: string; 'aria-hidden'?: boolean }) => (
    <span aria-label={props['aria-label']} aria-hidden={props['aria-hidden']} />
  ),
}));

// The real modal's focus-trap/portal mechanics are already covered by useZimmModal.test.tsx
// (synthetic harness) and footer/index.stories.tsx's SubscribeModalOpen play (mutation-tested,
// real browser). Stubbing it here keeps this suite scoped to ZimmSubscribeSection's own
// contract — does it wire the right props into its children — rather than a second copy of
// coverage that already exists elsewhere.
vi.mock('app/components/ui-kits/organisms/zimmSubscribeModal', () => ({
  ZimmSubscribeModal: ({
    isOpen,
    onClose,
    onSubmit,
  }: {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (firstName: string, lastName: string) => void;
  }) =>
    isOpen ? (
      <div role="dialog" aria-label="mock subscribe modal">
        <button onClick={() => onSubmit('Jane', 'Smith')}>mock-continue</button>
        <button onClick={onClose}>mock-cancel</button>
      </div>
    ) : null,
}));

// useSubscribeSection's own state machine (idle/unavailable/success/error transitions, modal
// open/close, pending-signup capture) is exhaustively covered by useSubscribeSection.test.ts.
// Mocking it here isolates this suite to ZimmSubscribeSection's own contract: given a state, does
// it render the right branch, and does it correctly wire DOM events into the hook's handlers.
vi.mock('app/hooks/useSubscribeSection', () => ({
  useSubscribeSection: vi.fn(),
}));

// UiCopyProvider's own fetch/lookup logic is covered by its own test file; mocking useUiCopy
// here isolates this suite to ZimmSubscribeSection's own contract rather than a second copy of
// that coverage. Default matches the no-Provider fallback behaviour real callers see in
// Storybook/production-before-content-exists.
vi.mock('app/hooks/useUiCopy', () => ({
  useUiCopy: vi.fn(),
}));

const mockUseSubscribeSection = vi.mocked(useSubscribeSection);
const mockUseUiCopy = vi.mocked(useUiCopy);

const baseProps = {
  heading: 'Keep in Touch',
  body: 'Sign up to stay up to date.',
  privacyPolicyHref: '/privacy-policy',
};

function mockHook(overrides: Partial<ReturnType<typeof useSubscribeSection>> = {}) {
  mockUseSubscribeSection.mockReturnValue({
    submitState: 'idle',
    modalOpen: false,
    closeModal: vi.fn(),
    handleEmailSubmit: vi.fn(),
    handleModalSubmit: vi.fn(),
    ...overrides,
  });
}

describe('ZimmSubscribeSection', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockHook();
    mockUseUiCopy.mockReturnValue({ t: (_key: string, fallback: string) => fallback, isLoading: false });
  });

  test('idle: renders the email input and Subscribe button, no success/error message', () => {
    render(<ZimmSubscribeSection {...baseProps} />);

    expect(screen.getByRole('textbox', { name: /email/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /subscribe/i })).toBeInTheDocument();
    expect(screen.queryByText(/on the list/i)).not.toBeInTheDocument();
    expect(screen.queryByRole('alert')).not.toBeInTheDocument();
  });

  test('success: renders the success message, not the input', () => {
    mockHook({ submitState: 'success' });
    render(<ZimmSubscribeSection {...baseProps} />);

    expect(screen.getByText(/on the list/i)).toBeInTheDocument();
    expect(screen.queryByRole('textbox', { name: /email/i })).not.toBeInTheDocument();
  });

  test('unavailable: renders the alert message, not the input', () => {
    mockHook({ submitState: 'unavailable' });
    render(<ZimmSubscribeSection {...baseProps} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/temporarily unavailable/i);
    expect(screen.queryByRole('textbox', { name: /email/i })).not.toBeInTheDocument();
  });

  test('error: renders the same alert message as unavailable (component does not distinguish them)', () => {
    mockHook({ submitState: 'error' });
    render(<ZimmSubscribeSection {...baseProps} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/temporarily unavailable/i);
  });

  test('enableNameCapture=false: never renders the modal, even if the hook reports modalOpen=true', () => {
    mockHook({ modalOpen: true });
    render(<ZimmSubscribeSection {...baseProps} enableNameCapture={false} />);

    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  });

  test('enableNameCapture=true, modalOpen=false: modal not rendered', () => {
    mockHook({ modalOpen: false });
    render(<ZimmSubscribeSection {...baseProps} enableNameCapture />);

    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  });

  test('enableNameCapture=true, modalOpen=true: modal renders', () => {
    mockHook({ modalOpen: true });
    render(<ZimmSubscribeSection {...baseProps} enableNameCapture />);

    expect(screen.getByRole('dialog')).toBeInTheDocument();
  });

  test('submitting the email form calls handleEmailSubmit with the typed value', async () => {
    const handleEmailSubmit = vi.fn();
    mockHook({ handleEmailSubmit });
    render(<ZimmSubscribeSection {...baseProps} />);

    await userEvent.type(screen.getByRole('textbox', { name: /email/i }), 'shopper@example.com');
    await userEvent.click(screen.getByRole('button', { name: /subscribe/i }));

    expect(handleEmailSubmit).toHaveBeenCalledWith('shopper@example.com');
  });

  test('modal continue calls handleModalSubmit with the entered names', async () => {
    const handleModalSubmit = vi.fn();
    mockHook({ modalOpen: true, handleModalSubmit });
    render(<ZimmSubscribeSection {...baseProps} enableNameCapture />);

    await userEvent.click(screen.getByRole('button', { name: 'mock-continue' }));

    expect(handleModalSubmit).toHaveBeenCalledWith('Jane', 'Smith');
  });

  test('uses the CMS-sourced email label and subscribe button text when useUiCopy resolves them', () => {
    mockUseUiCopy.mockReturnValue({
      t: (key: string, fallback: string) => {
        if (key === 'footer.subscribe.emailLabel') return 'E-mail';
        if (key === 'footer.subscribe.buttonLabel') return 'S’inscrire';
        return fallback;
      },
      isLoading: false,
    });
    render(<ZimmSubscribeSection {...baseProps} />);

    expect(screen.getByRole('textbox', { name: 'E-mail' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'S’inscrire' })).toBeInTheDocument();
  });

  test('uses the CMS-sourced success and unavailable messages when useUiCopy resolves them', () => {
    mockUseUiCopy.mockReturnValue({
      t: (key: string, fallback: string) => {
        if (key === 'footer.subscribe.successMessage') return 'Merci !';
        if (key === 'footer.subscribe.unavailableMessage') return 'Indisponible';
        return fallback;
      },
      isLoading: false,
    });

    mockHook({ submitState: 'success' });
    const { rerender } = render(<ZimmSubscribeSection {...baseProps} />);
    expect(screen.getByText('Merci !')).toBeInTheDocument();

    mockHook({ submitState: 'unavailable' });
    rerender(<ZimmSubscribeSection {...baseProps} />);
    expect(screen.getByRole('alert')).toHaveTextContent('Indisponible');
  });

  test('modal cancel calls closeModal', async () => {
    const closeModal = vi.fn();
    mockHook({ modalOpen: true, closeModal });
    render(<ZimmSubscribeSection {...baseProps} enableNameCapture />);

    await userEvent.click(screen.getByRole('button', { name: 'mock-cancel' }));

    expect(closeModal).toHaveBeenCalled();
  });
});

