import React, { type CSSProperties, useState } from 'react';
import { chakra } from '@chakra-ui/react';
import { ZimmTextInput } from '../../atoms/zimmTextInput';
import { ZimmButton } from '../../atoms/zimmButton';
import type { ZimmIconType } from '../../atoms/zimmIcon';

type ZimmInputActionProps = {
  label: string;
  type?: string;
  name?: string;
  icon?: ZimmIconType;
  buttonLabel?: string;
  errorText?: string;
  inverse?: boolean;
  disabled?: boolean;
  onSubmit?: (value: string) => void;
  style?: CSSProperties;
};

const DEFAULT_INPUT_NAME = 'zimm-input';
const VALIDATION_EMPTY = 'Please enter a value.';
const VALIDATION_EMAIL = 'Please enter a valid email address.';

/** Molecule — labelled text input with trailing icon-button. Mirrors zimm-input-action contract. */
export const ZimmInputAction = ({
  label,
  type = 'text',
  name,
  icon = 'chevron-right',
  buttonLabel = 'Submit',
  errorText,
  inverse = false,
  disabled = false,
  onSubmit,
  style,
}: ZimmInputActionProps) => {
  const [validationError, setValidationError] = useState<string | undefined>();

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    // namedItem returns Element | RadioNodeList | null; cast is safe here because the field is
    // always a single <input> (not a radio group) rendered by ZimmTextInput.
    const input = form.elements.namedItem(name || DEFAULT_INPUT_NAME) as HTMLInputElement | null;
    const value = (input?.value ?? '').trim();

    if (!value) {
      setValidationError(VALIDATION_EMPTY);
      return;
    }
    if (type === 'email' && !input?.checkValidity()) {
      setValidationError(VALIDATION_EMAIL);
      return;
    }
    setValidationError(undefined);
    onSubmit?.(value);
  };

  return (
    <chakra.form onSubmit={handleSubmit} noValidate __css={{ display: 'block', width: '100%' }} style={style}>
      <ZimmTextInput
        label={label}
        type={type}
        name={name || DEFAULT_INPUT_NAME}
        inverse={inverse}
        disabled={disabled}
        errorText={errorText ?? validationError}
        onChange={() => setValidationError(undefined)}
        trailing={
          <ZimmButton
            variant="icon"
            icon={icon}
            label={buttonLabel}
            type="submit"
            inverse={inverse}
            disabled={disabled}
          />
        }
      />
    </chakra.form>
  );
};

import { createContext, useContext } from 'react';

export type UiCopyContextValue = {
  /**
   * Returns the CMS value for `key`, or `fallback` while the fetch is loading, on fetch
   * error, or when no `uiCopy` entry with that key exists yet.
   */
  t: (key: string, fallback: string) => string;
  isLoading: boolean;
};

/**
 * Populated by UiCopyProvider (overrides/app/components/uiCopyProvider), mounted once in
 * _app-config. Not meant to be consumed directly — call useUiCopy() instead, which supplies
 * the no-Provider fallback.
 */
export const UiCopyContext = createContext<UiCopyContextValue | undefined>(undefined);

const FALLBACK_ONLY: UiCopyContextValue = {
  t: (_key: string, fallback: string) => fallback,
  isLoading: false,
};

/**
 * App-wide UI-copy lookup, backed by Contentful's uiCopy content type — one entry per string,
 * fetched in a single bulk call by UiCopyProvider and shared via context, the same pattern
 * this app already uses for translations (`useIntl`) rather than the per-page container-fetch
 * pattern commerce-sdk-react hooks use. uiCopy is app-wide static content, not page-specific
 * business data, so it's safe to call from any component — including presentational leaves —
 * without threading it through as a prop.
 *
 * Safe to call with no UiCopyProvider mounted above it (Storybook, an isolated unit test):
 * degrades to fallback-only text instead of throwing, so every call site stays functional and
 * testable with zero setup.
 *
 * @returns `t` lookup function plus `isLoading`
 */
export const useUiCopy = (): UiCopyContextValue => useContext(UiCopyContext) ?? FALLBACK_ONLY;

