import React, { useCallback, useMemo, type ReactNode } from 'react';
import { useContentfulEntries } from 'app/hooks/useContentful';
import { UiCopyContext } from 'app/hooks/useUiCopy';
import type { UiCopyEntry } from 'app/types/contentful';

type UiCopyProviderProps = {
  children: ReactNode;
};

/**
 * Bulk-fetches every `uiCopy` entry in one Delivery API call (`content_type=uiCopy`) and
 * provides the resulting key→value lookup to every descendant via useUiCopy() — mounted once
 * in _app-config, so creating N entries in Contentful costs one call for the whole app, not N
 * calls from N components each independently fetching the same content.
 *
 * @param props.children the app tree to provide uiCopy lookups to
 */
export const UiCopyProvider = ({ children }: UiCopyProviderProps) => {
  const { data, isLoading } = useContentfulEntries<UiCopyEntry>('uiCopy');

  const copyMap = useMemo(() => {
    const map = new Map<string, string>();
    (data ?? []).forEach((entry) => {
      map.set(entry.fields.key, entry.fields.value);
    });
    return map;
  }, [data]);

  // Fallback-on-failure by design, not just a loading placeholder: unlike structural content
  // (e.g. FooterContainer's footerConfig, which renders nothing rather than substitute
  // placeholder content), losing a button label or a status message to a Contentful outage
  // should never blank a control.
  const t = useCallback((key: string, fallback: string): string => copyMap.get(key) ?? fallback, [copyMap]);

  const value = useMemo(() => ({ t, isLoading }), [t, isLoading]);

  return <UiCopyContext.Provider value={value}>{children}</UiCopyContext.Provider>;
};

/**
 * Allow-list guard for hrefs that originate outside the codebase.
 *
 * Anything reaching an `href` from Contentful, a URL parameter, or a prop supplied by a
 * caller we do not control has to pass through here first. `javascript:` and `data:` URLs
 * execute; an authority reference like `//host` silently leaves the site. The `(?![/\\])`
 * lookahead rejects that, including the backslash form — a browser treats `/\host` as `//host`,
 * so a backslash is an authority reference just as much as a second slash is. `e9c2180` closed
 * only the forward-slash half; the backslash and control-character forms stayed open until now.
 *
 * Allow-list rather than deny-list on purpose: a deny-list has to anticipate every scheme,
 * and browsers keep adding them.
 */
// eslint-disable no-control-regex — the control characters ARE the subject here. The rule exists
// to catch them appearing by accident; these are deliberate, and matching them is the whole point
// of the fix. Suppressed at the point of use rather than in .eslintrc, per the escape-hatch
// convention in .claude/rules/typescript.md.
/* eslint-disable no-control-regex */
const C0_OR_SPACE = /^[\u0000-\u0020]+|[\u0000-\u0020]+$/g;
const TAB_LF_CR = /[\u0009\u000a\u000d]/g;
/* eslint-enable no-control-regex */

/**
 * Normalise the way the URL parser will, before testing.
 *
 * The WHATWG parser strips leading and trailing C0-or-space, and removes tab/LF/CR from anywhere
 * in the input, BEFORE it parses. `/\u0009/evil.com` is therefore parsed as `//evil.com`. Testing
 * the raw string means the allow-list checks a different value than the browser resolves — which
 * is exactly how the earlier fix passed its own tests while leaving the hole open.
 *
 * A plain space is deliberately not stripped: the parser percent-encodes it rather than removing
 * it, so `/ /evil.com` resolves on-site and must stay allowed.
 */
const normalise = (href: string): string => href.replace(C0_OR_SPACE, '').replace(TAB_LF_CR, '');

const SAFE_HREF_RE = /^(https?:|tel:|mailto:|#|\/(?![/\\]))/i;

/** True when `href` is safe to render on an anchor. Absent or unsafe values return false. */
export const isSafeHref = (href: string | undefined): boolean => (href ? SAFE_HREF_RE.test(normalise(href)) : false);

