34	 * Use for arrays where multiple non-conflicting regional entries can legitimately
35	 * coexist in the same rendered list (e.g. links inside a shared footerNavGroup).
36	 */
37	export function filterByRegion<T extends RegionAwareEntry>(entries: readonly T[], siteId: string): T[] {
38	  return entries.filter((entry) => isEligible(entry, siteId));
39	}
40	
41	/**
42	 * Single-winner resolution — picks the most specific entry eligible for `siteId`. Use
43	 * for a root entry where only one should render (e.g. which footerConfig to use for
44	 * the current site).
45	 *
46	 * A tie between two equally-scoped entries is an editorial mistake the additive-only sync
47	 * pipeline doesn't prevent (nothing stops two entries both scoping to e.g. exactly
48	 * ['ZimmermannUS'] — or two unscoped entries, which tie at Infinity). Resolved
49	 * deterministically by most-recently-updated, then by `sys.id` when those match, rather than
50	 * by CDA response order — and a console.warn fires on every tie, whichever side wins, so the
51	 * duplicate entry can be cleaned up. Fires n-1 times for an n-way tie, once per mount.
52	 */
