import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React from 'react';
import { expect, userEvent, within } from 'storybook/test';
import { Box } from '@chakra-ui/react';
import { ZimmTextInput } from '.';

const meta: Meta<typeof ZimmTextInput> = {
  title: 'Elements/ZimmTextInput',
  component: ZimmTextInput,
  parameters: {
    layout: 'padded',
  },
  argTypes: {
    label: { control: 'text' },
    type: { control: 'text' },
    name: { control: 'text' },
    inverse: { control: 'boolean' },
    disabled: { control: 'boolean' },
    helperText: { control: 'text' },
    errorText: { control: 'text' },
  },
};

export default meta;

type Story = StoryObj<typeof ZimmTextInput>;

export const Default: Story = {
  args: {
    label: 'Email address',
  },
};

export const Filled: Story = {
  args: {
    label: 'Email address',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const input = canvas.getByRole('textbox', { name: /email address/i });
    await userEvent.type(input, 'name@example.com');
    await expect(input).toHaveValue('name@example.com');
    // clearable defaults off, so a value alone must not produce a clear control —
    // the footer's subscribe field relies on this to show the submit chevron alone.
    await expect(canvas.queryByRole('button', { name: /clear input/i })).not.toBeInTheDocument();
  },
};

export const Clearable: Story = {
  name: 'Clearable — opt-in clear control',
  args: {
    label: 'Email address',
    clearable: true,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const input = canvas.getByRole('textbox', { name: /email address/i });
    await userEvent.type(input, 'name@example.com');
    const clearBtn = canvas.getByRole('button', { name: /clear input/i });
    await expect(clearBtn).toBeInTheDocument();
    await userEvent.click(clearBtn);
    await expect(input).toHaveFocus();
    await expect(input).toHaveValue('');
  },
};

export const WithHelperText: Story = {
  name: 'With Helper Text',
  args: {
    label: 'Email address',
    helperText: "We'll never share your email.",
  },
};

export const Disabled: Story = {
  args: {
    label: 'Email address',
    disabled: true,
  },
};

export const Error: Story = {
  args: {
    label: 'Email address',
    errorText: 'Please enter a valid email address',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByRole('alert')).toHaveTextContent('Please enter a valid email address');
    const input = canvas.getByRole('textbox', { name: /email address/i });
    await expect(input).toHaveAttribute('aria-invalid', 'true');
    await expect(input).toHaveAttribute('aria-describedby');
  },
};

export const Inverse: Story = {
  args: {
    label: 'Email address',
    inverse: true,
  },
  decorators: [
    (Story) => (
      <Box bg="background.05" p="xl">
        <Story />
      </Box>
    ),
  ],
};

export const InverseError: Story = {
  name: 'Inverse + Error',
  args: {
    label: 'Email address',
    inverse: true,
    errorText: 'Please enter a valid email address',
  },
  decorators: [
    (Story) => (
      <Box bg="background.05" p="xl">
        <Story />
      </Box>
    ),
  ],
};

