import React, { useId, type CSSProperties } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmIcon } from '../zimmIcon';
import { useZimmTextInputState } from 'app/hooks/useZimmTextInputState';

type ZimmTextInputProps = {
  label: string;
  type?: string;
  name?: string;
  inverse?: boolean;
  disabled?: boolean;
  helperText?: string;
  errorText?: string;
  onChange?: (value: string) => void;
  /** Controlled value — pass with `onChange` to let a parent form own the value. */
  value?: string;
  /** Initial value when uncontrolled. Ignored if `value` is provided. */
  defaultValue?: string;
  /**
   * Opt in to the clear-✕ shown once the field has a value. Defaults to false.
   *
   * Not in the design system: the extracted TextfieldV2 spec defines a `trailing-icon`
   * attribute and no `clearable` attribute, and SFCC-55's AC specifies the Stay in Touch
   * section as "an email input field and submit button" — two controls, not three. The
   * clear was originally added on the belief that Figma's footer glyph was an ✕; Kiera
   * confirmed (2026-08-20) it is the submit chevron, which `trailing` now carries.
   *
   * Kept as opt-in rather than deleted because a clear affordance is reasonable on a text
   * input atom (a search field would want one) — it just should not be the atom's decision
   * to impose. No consumer opts in today, so the footer renders one trailing control and
   * matches Figma.
   */
  clearable?: boolean;
  /**
   * Trailing icon-button slot. This IS in the design system: it maps to the extracted
   * TextfieldV2 spec's `trailing-icon` attribute (f2r/02-design/specs/components/text-input.md,
   * Figma node 40000265:374). ZimmInputAction injects the submit chevron here — Kiera confirmed
   * (2026-08-20) that the trailing glyph on the footer email field is the chevron, not an ✕.
   * Renders after the clear button below, which is a separate, unspecified addition.
   */
  trailing?: React.ReactNode;
  style?: CSSProperties;
};

/**
 * Atom — flush text input with floating label. Mirrors zimm-text-input contract
 * (flush + inverse variant).
 *
 * All styling lives in `zimmTextInput.css.ts`, co-located beside this file. The component owns only the
 * interaction state the theme cannot express: the value, focus, and whether the field is
 * filled — `filled` and `focused` are fed back into the recipe so it can resolve the
 * Figma colour cascade and the floated-label position.
 */
export const ZimmTextInput = ({
  label,
  type = 'text',
  name,
  inverse = false,
  disabled = false,
  helperText,
  errorText,
  onChange,
  value: controlledValue,
  defaultValue,
  clearable = false,
  trailing,
  style,
}: ZimmTextInputProps) => {
  const inputId = useId();
  const helperId = `${inputId}-helper`;
  const errorId = `${inputId}-error`;
  const hasError = !!errorText;

  const { value, focused, inputRef, handleChange, handleClear, setFocused } = useZimmTextInputState({
    onChange,
    value: controlledValue,
    defaultValue,
  });

  const styles = useMultiStyleConfig('ZimmTextInput', {
    inverse,
    disabled,
    hasError,
    focused,
    filled: value.length > 0,
  });

  return (
    <chakra.div __css={styles.root} style={style}>
      <chakra.div __css={styles.row}>
        {/* content — label + input stacked */}
        <chakra.div __css={styles.content}>
          <chakra.label htmlFor={inputId} __css={styles.label}>
            {label}
          </chakra.label>
          <chakra.input
            id={inputId}
            ref={inputRef}
            type={type}
            name={name}
            value={value}
            disabled={disabled}
            autoComplete={type === 'email' ? 'email' : undefined}
            onChange={handleChange}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            aria-invalid={hasError}
            aria-describedby={[helperText && helperId, hasError && errorId].filter(Boolean).join(' ') || undefined}
            __css={styles.input}
          />
        </chakra.div>
        {/* Clear-✕ — opt-in only, see `clearable` above. Renders before {trailing}, so a
            field that opts into both shows clear then trailing icon. */}
        {clearable && !disabled && value.length > 0 && (
          <chakra.button type="button" aria-label="Clear input" onClick={handleClear} __css={styles.clearButton}>
            <ZimmIcon type="close" size="sm" aria-hidden={true} />
          </chakra.button>
        )}
        {trailing}
      </chakra.div>
      {helperText && (
        <chakra.p id={helperId} __css={styles.helper}>
          {helperText}
        </chakra.p>
      )}
      {errorText && (
        <chakra.p id={errorId} role="alert" __css={styles.error}>
          {errorText}
        </chakra.p>
      )}
    </chakra.div>
  );
};

import { defineStyleConfig } from '@chakra-ui/react';

// Vertical leading around the label. Figma's footer-item allows equal space above and
// below the text and lets the item height follow the line count — 24px for one line,
// 38px for two (node 40000407:11736 > About Section > Links). Its text boxes are
// cap-height (8px one line, 22px two) where a browser line box is not, so the rule
// transfers rather than the numbers. The inner span reserves 1px for the underline
// indicator, so a line box measures 15px and two measure 29px; 4.5px each side yields
// 15+9=24 and 29+9=38 exactly. No 4.5px entry exists in spacing.ts — same provisional
// treatment as zimmButton.css.ts's BTN_PADDING_Y, pending UI-designer sign-off.
const NAV_ITEM_PAD_Y = '4.5px';

const baseStyle = {
  // textStyle is expanded in place by Chakra's style engine; fontFamily below
  // deliberately overrides it — Figma Default/Navigation binds brand/font/family/body,
  // not the heading family textStyles.navigation carries.
  textStyle: 'navigation',
  fontFamily: 'var(--zimm-font-family-body)',
  display: 'inline-flex',
  // Figma h-[24px] is a FLOOR, not a fixed height — the design's own ABOUT column
  // wraps "ACKNOWLEDGEMENT OF COUNTRY" onto two lines. minHeight keeps the 24px
  // target while letting multi-line labels grow, so no caller needs to override it.
  minHeight: 'var(--zimm-scale-xl)', // 1.5rem (24px) — Figma: h-[24px]
  // Height comes from lineHeight + padding, not from centring inside minHeight.
  // Centring only distributes space a single line leaves over, so a wrapped label
  // overflowed the floor and lost its leading entirely — the second line of
  // "ACKNOWLEDGEMENT OF COUNTRY" sat flush against the item above it.
  lineHeight: 'var(--zimm-font-lineheight-4xs)', // 0.875rem (14px)
  paddingBlock: NAV_ITEM_PAD_Y,
  justifyContent: 'center',
  alignItems: 'center',
  whiteSpace: 'normal',
  cursor: 'pointer',
  background: 'none',
  border: 'none',
  // paddingInline, not the `padding` shorthand: a shorthand here would sit after
  // paddingBlock above and reset it back to 0.
  paddingInline: 0,
  textDecoration: 'none',
  // Inner span carries the underline. Use transparent instead of 'none' so
  // border-color transitions smoothly on hover/active without a display change.
  '& > span': {
    borderBottom: 'var(--zimm-border-width-default) solid transparent',
    transition: `border-color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)`,
  },
  _hover: {
    '& > span': { borderBottomColor: 'currentColor' },
  },
  // Active (aria-current="page"): permanent underline regardless of hover
  '&[aria-current="page"] > span': {
    borderBottomColor: 'currentColor',
  },
};

const variants = {
  light: {
    color: 'var(--zimm-color-text-default)',
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
  inverse: {
    color: 'var(--zimm-color-text-inverse)',
    _focusVisible: {
      outline: 'var(--zimm-border-width-default) solid var(--zimm-color-text-inverse)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
};

export const ZimmNavItem = defineStyleConfig({
  baseStyle,
  variants,
  defaultProps: { variant: 'light' },
});

import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { ZimmSubscribeSection } from './index';

const meta: Meta<typeof ZimmSubscribeSection> = {
  title: 'Forms/ZimmSubscribeSection',
  component: ZimmSubscribeSection,
  // This organism's recipe hard-codes inverse (light-on-dark) colours with no light variant, so
  // mounted in isolation on Storybook's white canvas its own text is unreadable and axe fails it:
  // the `heading` part (--zimm-color-text-inverse-grey, #969696) came out at 2.95:1 against white,
  // below the 4.5:1 AA floor for 12px/500. That's an artefact of the isolated mount, not a defect
  // — in the footer this sits inside the `container` part, which is the only background in the
  // chain (footer.css.ts:25, --zimm-color-bg-05 / #191919), where the same colour is 5.94:1 and
  // passes. Worse, the `body` and input are --zimm-color-text-inverse (#ffffff), i.e. white on
  // white at 1:1 — invisible, and axe did not even report those. This decorator reproduces the
  // shipped background so the a11y check measures the context the component actually renders in.
  decorators: [
    (Story) => (
      <div style={{ backgroundColor: 'var(--zimm-color-bg-05)', padding: 'var(--zimm-scale-2xl)' }}>
        <Story />
      </div>
    ),
  ],
  // No canvas-background setting here on purpose. A `parameters: {backgrounds: {default: 'dark'}}`
  // used to sit at this spot and was a silent no-op — Storybook 10 reads the selection from
  // `globals.backgrounds.value`, and nothing reads `parameters…default` — which is part of why the
  // a11y failure surfaced. The obvious repair, `globals: {backgrounds: {value: 'dark'}}`, was
  // rejected: Storybook's built-in `dark` is #333 against this decorator's #191919, so it would
  // introduce a second, underived dark that can drift from the token. The decorator is the only
  // surface axe or the eye needs.
  args: {
    heading: 'Keep in touch',
    body: 'Be the first to know about new collections and new arrivals.',
    privacyPolicyHref: '/privacy-policy',
  },
};
export default meta;
type Story = StoryObj<typeof ZimmSubscribeSection>;

export const Default: Story = {};

export const Subscribed: Story = {
  args: { initialSubscribed: true },
};

/**
 * Full email → modal → submit interaction coverage (including the a11y/focus assertions) lives
 * at the footer assembly level — footer/index.stories.tsx's SubscribeSubmit and
 * SubscribeModalOpen — since that's the shipped context and testing.md says prove behaviour
 * once, at the cheapest layer. These stories exist for components.md's per-exported-component
 * requirement and for visual variants when this organism is placed elsewhere.
 */
export const NameCaptureEnabled: Story = {
  name: 'Name capture modal enabled (HPC-035, not shipped)',
  args: { enableNameCapture: true },
};

