import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { FooterNavColumn, hasIntentionalLineBreak } from './index';
import type { FooterNavGroupEntry, LinkEntry } from 'app/types/contentful';

// ZimmIcon pulls in the base SFCC icons barrel (app/components/icons), which has a top-level
// side effect (AmexSymbol.viewBox = ...) that throws under Vitest — SVG imports resolve to raw
// path strings here, not components. No test in this repo has rendered an icon-consuming
// component before, so this gap was never caught; fixing the SVG transform lives in
// vitest.config.ts, Tier 1 test config this task cannot touch. Mocking the smallest surface
// (ZimmIcon itself) routes around it without losing anything this test actually asserts on —
// the aria-label/href under test come from ZimmContactIconRow's own wrapper, not from ZimmIcon.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  // Forwards aria-label/aria-hidden — ZimmContactIconRow's fallback (no-href) branch puts the
  // accessible name on ZimmIcon itself, not on its wrapper, so a no-op stub would silently drop
  // the exact a11y contract this test suite asserts on.
  ZimmIcon: (props: { 'aria-label'?: string; 'aria-hidden'?: boolean }) => (
    <span aria-label={props['aria-label']} aria-hidden={props['aria-hidden']} />
  ),
}));

const makeLink = (id: string, label: string, href = '#'): LinkEntry => ({
  sys: { id, contentType: { sys: { id: 'link' } } },
  fields: { label, href },
});

const makeGroup = (overrides: Partial<FooterNavGroupEntry['fields']> = {}): FooterNavGroupEntry => ({
  sys: { id: 'group-test', contentType: { sys: { id: 'footerNavGroup' } } },
  fields: {
    heading: 'About',
    links: [makeLink('link-1', 'Our Story'), makeLink('link-2', 'Careers')],
    ...overrides,
  },
});

describe('hasIntentionalLineBreak', () => {
  test('true for a label carrying a non-breaking space', () => {
    expect(hasIntentionalLineBreak('Acknowledgement of Country')).toBe(true);
  });
=== CONTACT ICON ROW STORIES ===
import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, within } from 'storybook/test';
import { ZimmContactIconRow } from './index';

const meta: Meta<typeof ZimmContactIconRow> = {
  title: 'Elements/ZimmContactIconRow',
  component: ZimmContactIconRow,
  parameters: { backgrounds: { default: 'dark' } },
};
export default meta;
type Story = StoryObj<typeof ZimmContactIconRow>;

export const Default: Story = {
  args: {
    phoneHref: 'tel:+61280000000',
    whatsAppHref: 'https://wa.me/61280000000',
    emailHref: 'mailto:care@zimmermann.com',
  },
  // Asserts leavesTheSite's scheme branch. Security-adjacent: rel="noopener noreferrer" is what
  // stops the storefront URL reaching WhatsApp in the Referer header, and the accessible-name
  // suffix is WCAG 3.2.5.
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    const whatsApp = canvas.getByRole('link', { name: /whatsapp/i });
    await expect(whatsApp).toHaveAttribute('target', '_blank');
    await expect(whatsApp).toHaveAttribute('rel', 'noopener noreferrer');
    await expect(whatsApp).toHaveAccessibleName(/opens in a new tab/i);

    for (const name of [/call us/i, /email us/i]) {
      const link = canvas.getByRole('link', { name });
      await expect(link).not.toHaveAttribute('target');
      await expect(link).not.toHaveAccessibleName(/opens in a new tab/i);
    }
  },
};

/**
 * Absent and unsafe hrefs both fall through to a labelled, non-interactive span — see the
 * isSafeHref guard in index.tsx. Footer-level coverage of this same branch, in context, lives in
 * footer/index.stories.tsx's ContactChannelFallbacks; this is the isolated version.
 */
export const NoUsableDestination: Story = {
  name: 'Absent and unsafe hrefs',
  args: {
    phoneHref: undefined,
    whatsAppHref: 'javascript:alert(1)',
    emailHref: 'mailto:care@zimmermann.com',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    for (const name of [/call us/i, /whatsapp/i]) {
      await expect(canvas.queryByRole('link', { name })).not.toBeInTheDocument();
      await expect(canvas.getByRole('img', { name })).toBeInTheDocument();
    }
    await expect(canvas.getByRole('link', { name: /email us/i })).toHaveAttribute('href', 'mailto:care@zimmermann.com');
  },
};

